import { gisApi } from '@/lib/gisApi'
import type { GISAsetReference, GISAdministrasiReference, GISCapabilities, GISDataset, GISDraftFeature, GISImport, GISKerjaSamaReference, GISKind, GISOverlapWarning } from '@/types/gis'

const KIND_LABEL: Record<GISKind, string> = { konsesi: 'Konsesi tanah', tanaman: 'Blok tanaman', hutan: 'Kawasan hutan', opset: 'Area OPSET kerja sama', okupasi: 'Okupasi', administrasi: 'Batas administrasi' }
const KIND_COLOR: Record<GISKind, string> = { konsesi: 'bg-yellow-100 text-yellow-800', tanaman: 'bg-lime-100 text-lime-800', hutan: 'bg-green-100 text-green-800', opset: 'bg-cyan-100 text-cyan-800', okupasi: 'bg-red-100 text-red-800', administrasi: 'bg-slate-100 text-slate-700' }
const DOMAIN_BY_KIND: Record<GISKind, string> = { konsesi: 'legal', tanaman: 'tanaman', hutan: 'referensi', opset: 'opset', okupasi: 'legal', administrasi: 'referensi' }
const ADMIN_LEVEL_LABEL: Record<GISAdministrasiReference['level'], string> = { provinsi: 'Provinsi', kabupaten_kota: 'Kabupaten/kota', kecamatan: 'Kecamatan', desa_kelurahan: 'Desa/kelurahan' }
type Field = { key: string; label: string; type?: 'number' | 'date' | 'select'; options?: Array<[string, string]>; advanced?: boolean }
const FIELDS: Record<GISKind, Field[]> = {
  konsesi: [{ key: 'nomor_alas_hak', label: 'Nomor alas hak' }, { key: 'jenis_alas_hak', label: 'Jenis alas hak' }, { key: 'declared_area_m2', label: 'Luas dokumen (m²)', type: 'number' }, { key: 'tanggal_terbit', label: 'Tanggal terbit', type: 'date', advanced: true }, { key: 'tanggal_mulai', label: 'Tanggal mulai berlaku', type: 'date', advanced: true }, { key: 'expiry_mode', label: 'Masa berlaku', type: 'select', options: [['fixed', 'Tanggal tertentu'], ['indefinite', 'Tidak terbatas'], ['unknown', 'Belum diketahui']], advanced: true }, { key: 'tanggal_berakhir', label: 'Tanggal berakhir', type: 'date', advanced: true }, { key: 'pemegang_hak', label: 'Pemegang hak', advanced: true }, { key: 'lokasi', label: 'Lokasi dokumen', advanced: true }, { key: 'sumber_dokumen', label: 'Sumber dokumen', advanced: true }, { key: 'catatan', label: 'Catatan', advanced: true }],
  tanaman: [{ key: 'unit_kebun', label: 'Unit/kebun' }, { key: 'kode_blok', label: 'Kode blok' }, { key: 'komoditas', label: 'Komoditas' }, { key: 'tahun_tanam', label: 'Tahun tanam', type: 'number' }, { key: 'declared_area_m2', label: 'Luas dokumen (m²)', type: 'number' }],
  hutan: [{ key: 'fungsi_normalized', label: 'Status kawasan hutan', type: 'select', options: [['Hutan Lindung', 'Hutan Lindung'], ['Hutan Produksi', 'Hutan Produksi'], ['Hutan Produksi Terbatas', 'Hutan Produksi Terbatas'], ['Hutan Konservasi', 'Hutan Konservasi'], ['Hutan Produksi yang dapat Dikonversi', 'Hutan Produksi yang dapat Dikonversi'], ['Areal Penggunaan Lain', 'Areal Penggunaan Lain'], ['Lainnya', 'Lainnya']] }, { key: 'fungsi_asli', label: 'Status asli sumber' }, { key: 'sumber', label: 'Sumber' }, { key: 'tahun', label: 'Tahun', type: 'number' }, { key: 'nomor_sk', label: 'Nomor SK' }, { key: 'tanggal_sk', label: 'Tanggal SK', type: 'date' }],
  opset: [{ key: 'kerja_sama_id', label: 'Perjanjian kerja sama', type: 'select' }, { key: 'jenis_alas_hak', label: 'Jenis alas hak', advanced: true }, { key: 'nomor_alas_hak', label: 'Nomor alas hak', advanced: true }, { key: 'nama_mitra', label: 'Nama mitra', advanced: true }, { key: 'no_perjanjian', label: 'Nomor perjanjian', advanced: true }, { key: 'skema_kerja_sama', label: 'Skema kerja sama', advanced: true }, { key: 'tanggal_mulai', label: 'Tanggal mulai', type: 'date', advanced: true }, { key: 'tanggal_berakhir', label: 'Tanggal berakhir', type: 'date', advanced: true }, { key: 'luas_dokumen_m2', label: 'Luas dokumen (m²)', type: 'number', advanced: true }, { key: 'lokasi', label: 'Lokasi dokumen', advanced: true }, { key: 'sumber_dokumen', label: 'Sumber dokumen', advanced: true }, { key: 'catatan', label: 'Catatan', advanced: true }],
  okupasi: [{ key: 'pihak_pengokupasi', label: 'Pihak pengokupasi' }, { key: 'declared_area_m2', label: 'Luas dokumen (m²)', type: 'number' }, { key: 'catatan', label: 'Catatan' }],
  administrasi: [{ key: 'level', label: 'Tingkat batas', type: 'select', options: [['provinsi', 'Provinsi'], ['kabupaten_kota', 'Kabupaten/kota'], ['kecamatan', 'Kecamatan'], ['desa_kelurahan', 'Desa/kelurahan']] }, { key: 'region_code', label: 'Kode wilayah' }, { key: 'region_name', label: 'Nama wilayah' }, { key: 'sumber', label: 'Sumber' }, { key: 'tahun', label: 'Tahun', type: 'number' }],
}
const OTHER_DETAILS: Field[] = [{ key: 'tanggal_mulai', label: 'Tanggal mulai', type: 'date', advanced: true }, { key: 'tanggal_berakhir', label: 'Tanggal berakhir', type: 'date', advanced: true }, { key: 'lokasi', label: 'Lokasi dokumen', advanced: true }, { key: 'sumber_dokumen', label: 'Sumber dokumen', advanced: true }]
for (const kind of ['tanaman', 'hutan', 'okupasi', 'administrasi'] as GISKind[]) FIELDS[kind].push(...OTHER_DETAILS, ...(kind === 'tanaman' ? [{ key: 'pemegang_hak', label: 'Pemegang hak', advanced: true }, { key: 'catatan', label: 'Catatan', advanced: true }] : kind !== 'okupasi' ? [{ key: 'catatan', label: 'Catatan', advanced: true }] : []))

const FIELD_LABEL: Record<string, string> = Object.fromEntries(Object.values(FIELDS).flat().map(field => [field.key, field.label]))

function FeatureField({ field, value, onChange, required, kerjaSama }: { field: Field; value: string | number; onChange: (value: string) => void; required: boolean; kerjaSama: GISKerjaSamaReference[] }) {
  return <div><Label>{field.label}{required && <span className="ml-1 text-red-600">*</span>}</Label>{field.type === 'select' ? <Select value={String(value)} onValueChange={onChange}><SelectTrigger className="mt-1"><SelectValue placeholder="Pilih" /></SelectTrigger><SelectContent>{field.key === 'kerja_sama_id' ? kerjaSama.map(item => <SelectItem key={item.id} value={item.id}>{item.nama_mitra} · {item.no_perjanjian ?? 'tanpa nomor'}</SelectItem>) : field.options?.map(([option, label]) => <SelectItem key={option} value={option}>{label}</SelectItem>)}</SelectContent></Select> : <Input className="mt-1" type={field.type ?? 'text'} value={String(value)} onChange={event => onChange(event.target.value)} />}</div>
}

function emptyDraft(feature: GISDraftFeature) {
  return Object.fromEntries(Object.entries(feature.attributes).map(([key, value]) => [key, value ?? ''])) as Record<string, string | number>
}

export default function GISMap() {
  const uploadInputRef = useRef<HTMLInputElement>(null)
  const managePanelRef = useRef<HTMLDivElement>(null)
  const reviewPanelRef = useRef<HTMLDivElement>(null)
  const [capabilities, setCapabilities] = useState<GISCapabilities | null>(null)
  const [datasets, setDatasets] = useState<GISDataset[]>([])
  const [enabled, setEnabled] = useState<string[]>([])
  const [layerKindFilter, setLayerKindFilter] = useState<GISKind | 'all'>('all')
  const [adminLevel, setAdminLevel] = useState<GISAdministrasiReference['level'] | 'all'>('all')
  const [adminRegions, setAdminRegions] = useState<GISAdministrasiReference[]>([])
  const [adminCode, setAdminCode] = useState('')
  const [hutanFunctions, setHutanFunctions] = useState<string[]>([])
  const [hutanFunction, setHutanFunction] = useState('all')
  const [bbox, setBbox] = useState('95,-11,141,6')
  const [zoomTarget, setZoomTarget] = useState<{ bbox: string; request: number } | null>(null)
  const [features, setFeatures] = useState<Awaited<ReturnType<typeof gisApi.features>> | null>(null)
  const [selectedDatasetId, setSelectedDatasetId] = useState('')
  const [activeImport, setActiveImport] = useState<GISImport | null>(null)
  const [draftFeatures, setDraftFeatures] = useState<GISDraftFeature[]>([])
  const [activeDraftLayers, setActiveDraftLayers] = useState<Array<{ dataset: GISDataset; features: GISDraftFeature[] }>>([])
  const [previewDraftIds, setPreviewDraftIds] = useState<string[]>([])
  const [selectedFeatureId, setSelectedFeatureId] = useState('')
  const [draft, setDraft] = useState<Record<string, string | number>>({})
  const [featureName, setFeatureName] = useState('')
  const [sourceDraft, setSourceDraft] = useState<Record<string, string | number | boolean | null>>({})
  const [newSourceKey, setNewSourceKey] = useState('')
  const [bulkDraft, setBulkDraft] = useState<Record<string, string | number>>({})
  const [bulkOpen, setBulkOpen] = useState(false)
  const [featureSearch, setFeatureSearch] = useState('')
  const [kerjaSama, setKerjaSama] = useState<GISKerjaSamaReference[]>([])
  const [asetReferences, setAsetReferences] = useState<GISAsetReference[]>([])
  const [linkedAssetIds, setLinkedAssetIds] = useState<string[]>([])
  const [overlaps, setOverlaps] = useState<{ state: string; data: GISOverlapWarning[] } | null>(null)
  const [createOpen, setCreateOpen] = useState(false)
  const [newKind, setNewKind] = useState<GISKind>('konsesi')
  const [newName, setNewName] = useState('')
  const [newScope, setNewScope] = useState('')
  const [pendingFile, setPendingFile] = useState<File | null>(null)
  const [uploadKind, setUploadKind] = useState<GISKind>('konsesi')
  const [uploadDatasetId, setUploadDatasetId] = useState('new')
  const [uploadLayerName, setUploadLayerName] = useState('')
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)
  const [workspace, setWorkspace] = useState<'peta' | 'aset' | 'kelola'>('peta')
  const [assetFocusBbox, setAssetFocusBbox] = useState<string | null>(null)
  const [searchParams] = useSearchParams()
  const focusAsetId = searchParams.get('aset')
  const [manageDatasets, setManageDatasets] = useState<GISDataset[]>([])
  const [manageShowArchived, setManageShowArchived] = useState(true)
  const [renameTarget, setRenameTarget] = useState<GISDataset | null>(null)
  const [renameValue, setRenameValue] = useState('')
  const [archiveTarget, setArchiveTarget] = useState<GISDataset | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<GISDataset | null>(null)

  const selectedDataset = datasets.find(item => item.id === selectedDatasetId) ?? null
  const selectedFeature = draftFeatures.find(item => item.id === selectedFeatureId) ?? null
  const missingById = useMemo(() => new globalThis.Map((activeImport?.validation_report.missing_attributes ?? []).map(item => [item.feature_id, item.fields])), [activeImport])
  const missingSummary = useMemo(() => {
    const counts = new globalThis.Map<string, number>()
    for (const fields of missingById.values()) {
      for (const field of fields.split(', ').filter(Boolean)) counts.set(field, (counts.get(field) ?? 0) + 1)
    }
    return Array.from(counts.entries()).sort(([, left], [, right]) => right - left)
  }, [missingById])
  const filteredDatasets = useMemo(() => datasets.filter(item => layerKindFilter === 'all' || item.kind === layerKindFilter), [datasets, layerKindFilter])
  const reviewFeatures = useMemo(() => {
    const query = featureSearch.trim().toLocaleLowerCase('id-ID')
    return draftFeatures.filter(feature => !query || feature.name.toLocaleLowerCase('id-ID').includes(query) || missingById.get(feature.id)?.toLocaleLowerCase('id-ID').includes(query))
  }, [draftFeatures, featureSearch, missingById])
  const activeVersions = useMemo(() => datasets.filter(item => enabled.includes(item.id) && (layerKindFilter === 'all' || item.kind === layerKindFilter) && (hutanFunction === 'all' || item.kind === 'hutan')).map(item => item.active_version_id).filter((id): id is string => Boolean(id)), [datasets, enabled, layerKindFilter, hutanFunction])
  const mapFeatures = useMemo(() => {
    const usesDraft = (dataset: GISDataset) => !dataset.active_version_id || previewDraftIds.includes(dataset.id)
    const selectedPreview = Boolean(activeImport && selectedDataset && enabled.includes(selectedDataset.id) && usesDraft(selectedDataset))
    const previewLayers = activeDraftLayers.filter(layer => enabled.includes(layer.dataset.id) && usesDraft(layer.dataset) && !(selectedPreview && layer.dataset.id === selectedDataset?.id))
    const draftDatasetIds = new Set(previewLayers.map(layer => layer.dataset.id))
    if (selectedPreview && selectedDataset) draftDatasetIds.add(selectedDataset.id)
    return { type: 'FeatureCollection' as const, features: [...(features?.features ?? []).filter(feature => !draftDatasetIds.has(feature.properties.dataset_id ?? '')), ...(selectedPreview && selectedDataset ? draftFeatures.map(feature => ({ type: 'Feature' as const, id: feature.id, properties: { feature_id: feature.id, dataset_id: selectedDataset.id, name: feature.name, kind: selectedDataset.kind, computed_area_m2: feature.computed_area_m2, attributes: feature.attributes, preview: true }, geometry: feature.geometry })) : []), ...previewLayers.flatMap(layer => layer.features.map(feature => ({ type: 'Feature' as const, id: feature.id, properties: { feature_id: feature.id, dataset_id: layer.dataset.id, name: feature.name, kind: layer.dataset.kind, computed_area_m2: feature.computed_area_m2, attributes: feature.attributes, preview: true }, geometry: feature.geometry })))] }
  }, [features, activeImport, selectedDataset, draftFeatures, enabled, activeDraftLayers, previewDraftIds])
  const canWrite = selectedDataset ? Boolean(capabilities?.domains.includes(DOMAIN_BY_KIND[selectedDataset.kind])) : false
  const canUpload = Boolean(capabilities?.domains.length)
  const canDownloadSelected = Boolean(selectedDataset?.active_version_id || activeImport || activeDraftLayers.some(layer => layer.dataset.id === selectedDataset?.id))
  const manageLayer = (dataset: GISDataset) => {
    setSelectedDatasetId(dataset.id)
    setWorkspace('peta')
    window.setTimeout(() => managePanelRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0)
  }
  const zoomToLayer = async (dataset: GISDataset) => {
    try {
      const { bbox: targetBbox } = await gisApi.datasetBounds(dataset.id)
      if (!targetBbox) { setMessage(`Layer "${dataset.name}" belum memiliki geometri. Unggah ulang KML jika impor sebelumnya gagal.`); return }
      setEnabled(current => current.includes(dataset.id) ? current : [...current, dataset.id])
      setAssetFocusBbox(null)
      setZoomTarget(current => ({ bbox: targetBbox, request: (current?.request ?? 0) + 1 }))
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal mencari lokasi layer.') }
  }

  const loadDatasets = useCallback(async () => {
    try {
      const [nextCapabilities, result] = await Promise.all([gisApi.capabilities(), gisApi.datasets()])
      setCapabilities(nextCapabilities); setDatasets(result.data)
      setEnabled(previous => previous.length ? previous.filter(id => result.data.some(item => item.id === id)) : result.data.filter(item => item.kind !== 'administrasi').map(item => item.id))
      setSelectedDatasetId(previous => previous || (result.data.find(item => item.kind === 'konsesi') ?? result.data[0])?.id || '')
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal memuat layer GIS.') }
  }, [])
  const loadDraft = useCallback(async (importId: string, preferredFeatureId?: string) => {
    const [nextImport, result] = await Promise.all([gisApi.getImport(importId), gisApi.importFeatures(importId)])
    setActiveImport(nextImport.import); setDraftFeatures(result.data)
    const first = result.data.find(feature => feature.id === preferredFeatureId) ?? result.data.find(feature => nextImport.import.validation_report.missing_attributes?.some(item => item.feature_id === feature.id)) ?? result.data[0]
    setSelectedFeatureId(first?.id ?? ''); setDraft(first ? emptyDraft(first) : {})
  }, [])
  const loadManageDatasets = useCallback(async () => {
    try { const result = await gisApi.datasets(undefined, manageShowArchived); setManageDatasets(result.data) }
    catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal memuat daftar layer.') }
  }, [manageShowArchived])

  useEffect(() => { void loadDatasets() }, [loadDatasets])
  useEffect(() => {
    if (!focusAsetId) return
    let cancelled = false
    setWorkspace('peta')
    void gisApi.assetBounds(focusAsetId).then(result => {
      if (cancelled) return
      if (!result.bbox) { setAssetFocusBbox(null); setMessage('Aset ini belum terhubung ke poligon konsesi atau area OPSET di peta. Hubungkan aset pada atribut poligon konsesi agar lokasinya dapat ditampilkan.'); return }
      setEnabled(current => current.length ? Array.from(new Set([...current, ...result.dataset_ids])) : current)
      setZoomTarget(null)
      setAssetFocusBbox(result.bbox)
    }).catch(error => { if (!cancelled) setMessage(error instanceof Error ? error.message : 'Gagal mencari lokasi aset.') })
    return () => { cancelled = true }
  }, [focusAsetId])
  useEffect(() => { if (workspace === 'kelola') void loadManageDatasets() }, [workspace, loadManageDatasets])
  useEffect(() => { if (!selectedDataset) return; let cancelled = false; setActiveImport(null); setDraftFeatures([]); setSelectedFeatureId(''); setFeatureSearch(''); if (!canWrite) return; void gisApi.latestImport(selectedDataset.id).then(async result => { if (cancelled || !result.import) return; if (['mapping_required', 'ready'].includes(result.import.state)) await loadDraft(result.import.id); else if (result.import.state === 'failed') setMessage(`Impor terakhir gagal: ${result.import.validation_report.error ?? 'Berkas tidak dapat diproses.'}`); else if (['uploaded', 'processing'].includes(result.import.state)) setMessage('Impor terakhir masih diproses. Halaman ini dapat ditinjau saat selesai.') }).catch(error => { if (!cancelled) setMessage(error instanceof Error ? error.message : 'Gagal memuat status impor.') }); return () => { cancelled = true } }, [selectedDataset?.id, canWrite, loadDraft])
  useEffect(() => { let cancelled = false; const activeDatasets = datasets.filter(item => enabled.includes(item.id) && (item.id !== selectedDataset?.id || !canWrite)); void Promise.all(activeDatasets.map(async dataset => { try { const latest = await gisApi.latestImport(dataset.id); if (!latest.import || !['mapping_required', 'ready'].includes(latest.import.state)) return null; const result = await gisApi.importFeatures(latest.import.id); return { dataset, features: result.data } } catch { return null } })).then(items => { if (!cancelled) setActiveDraftLayers(items.filter((item): item is { dataset: GISDataset; features: GISDraftFeature[] } => item !== null)) }); return () => { cancelled = true } }, [datasets, enabled, selectedDataset?.id, activeImport?.id, canWrite])
  useEffect(() => { if (activeVersions.length) void gisApi.features(bbox, activeVersions, { adminLevel: adminLevel === 'all' ? undefined : adminLevel, adminRegionCode: adminCode || undefined, hutanFunction: hutanFunction === 'all' ? undefined : hutanFunction }).then(setFeatures).catch(error => setMessage(error.message)); else setFeatures({ type: 'FeatureCollection', features: [] }) }, [bbox, activeVersions, adminLevel, adminCode, hutanFunction])
  useEffect(() => { if (selectedDataset?.kind === 'opset') void gisApi.kerjaSamaReference().then(result => setKerjaSama(result.data)).catch(error => setMessage(error.message)) }, [selectedDataset?.kind])
  useEffect(() => { if (selectedDataset?.kind === 'konsesi') void gisApi.asetReference().then(result => setAsetReferences(result.data)).catch(error => setMessage(error.message)) }, [selectedDataset?.kind])
  useEffect(() => { if (adminLevel === 'all') { setAdminRegions([]); setAdminCode(''); return }; void gisApi.administrasiReference(adminLevel).then(result => { setAdminRegions(result.data); setAdminCode('') }).catch(error => setMessage(error.message)) }, [adminLevel])
  useEffect(() => { void gisApi.hutanFunctions().then(result => setHutanFunctions(result.data)).catch(error => setMessage(error.message)) }, [])
  useEffect(() => { if (selectedDataset?.active_version_id) void gisApi.overlapWarnings(selectedDataset.id).then(setOverlaps).catch(error => setMessage(error.message)); else setOverlaps(null) }, [selectedDataset?.id, selectedDataset?.active_version_id])
  useEffect(() => { if (selectedFeature) { setDraft(emptyDraft(selectedFeature)); setFeatureName(selectedFeature.name); setSourceDraft(Object.fromEntries(Object.entries(selectedFeature.original_properties).filter(([, value]) => value === null || ['string', 'number', 'boolean'].includes(typeof value))) as Record<string, string | number | boolean | null>); setNewSourceKey(''); setLinkedAssetIds(selectedFeature.linked_asset_ids) } }, [selectedFeature])

  const createDataset = async () => { if (!newName.trim()) { setMessage('Nama layer wajib diisi.'); return }; setBusy(true); try { const result = await gisApi.createDataset({ kind: newKind, name: newName.trim(), scope_key: newScope.trim() }); setDatasets(items => [result.dataset, ...items]); setSelectedDatasetId(result.dataset.id); setCreateOpen(false); setNewName(''); setNewScope(''); setMessage('Layer draf dibuat. Unggah berkas spasial untuk memulai versi pertama.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal membuat layer.') } finally { setBusy(false) } }
  const beginUpload = (file?: File, targetDatasetId = 'new') => { if (!file) return; const target = datasets.find(item => item.id === targetDatasetId) ?? null; setPendingFile(file); setUploadKind(target?.kind ?? selectedDataset?.kind ?? 'konsesi'); setUploadDatasetId(target?.id ?? 'new'); setUploadLayerName(target?.name ?? file.name.replace(/\.(kml|kmz|geojson|json|zip|gpkg)$/i, '')); }
  const processUpload = async (file: File, dataset: GISDataset) => { setBusy(true); setMessage('Berkas disimpan dan sedang diproses…'); try { const result = await gisApi.importFile(dataset.id, file); for (let attempt = 0; attempt < 45; attempt += 1) { await new Promise(resolve => window.setTimeout(resolve, 1000)); const status = await gisApi.getImport(result.import_id); if (!['uploaded', 'processing'].includes(status.import.state)) { if (status.import.state === 'failed') { setActiveImport(status.import); setDraftFeatures([]); setMessage(`Impor gagal: ${status.import.validation_report.error ?? 'Berkas tidak dapat diproses.'}`); return }; await loadDraft(result.import_id); setPreviewDraftIds(ids => ids.includes(dataset.id) ? ids : [...ids, dataset.id]); setMessage(status.import.state === 'ready' ? 'Data KML/KMZ telah terbaca lengkap dan siap diterbitkan.' : 'Geometri siap. Isi hanya metadata yang belum ditemukan dalam berkas.'); return } }; setMessage('Impor masih diproses. Muat ulang halaman ini beberapa saat lagi.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal mengunggah berkas.') } finally { setBusy(false) } }
  const upload = (file?: File) => beginUpload(file, selectedDataset?.id ?? 'new')
  const confirmUpload = async () => { if (!pendingFile) return; let dataset = datasets.find(item => item.id === uploadDatasetId) ?? null; if (!dataset) { if (!uploadLayerName.trim()) { setMessage('Nama layer wajib diisi.'); return }; setBusy(true); try { const result = await gisApi.createDataset({ kind: uploadKind, name: uploadLayerName.trim(), scope_key: '' }); dataset = result.dataset; setDatasets(items => [dataset!, ...items]); setSelectedDatasetId(dataset.id) } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal membuat layer.'); setBusy(false); return } }; if (dataset.kind !== uploadKind) { setMessage('Jenis data harus sesuai dengan layer tujuan.'); return }; setEnabled(current => current.includes(dataset.id) ? current : [...current, dataset.id]); setPendingFile(null); await processUpload(pendingFile, dataset) }
  const saveFeature = async () => { if (!activeImport || !selectedFeature) return; if (!featureName.trim()) { setMessage('Nama poligon wajib diisi.'); return }; setBusy(true); try { const result = await gisApi.updateDraftFeature(activeImport.id, selectedFeature.id, { name: featureName.trim(), original_properties: sourceDraft, attributes: draft, linked_asset_ids: selectedDataset?.kind === 'konsesi' ? linkedAssetIds : undefined, expected_draft_revision: activeImport.draft_revision }); await loadDraft(activeImport.id, selectedFeature.id); setMessage(result.state === 'ready' ? 'Koreksi disimpan. Versi siap diterbitkan.' : 'Koreksi disimpan. Lengkapi data yang masih bertanda wajib.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal menyimpan atribut.') } finally { setBusy(false) } }
  const beginEdit = async (dataset: GISDataset) => { setBusy(true); try { const result = await gisApi.beginEdit(dataset.id); setSelectedDatasetId(dataset.id); setWorkspace('peta'); setEnabled(current => current.includes(dataset.id) ? current : [...current, dataset.id]); await loadDraft(result.import_id); setPreviewDraftIds(ids => ids.includes(dataset.id) ? ids : [...ids, dataset.id]); setMessage(result.reused ? 'Draf koreksi yang sudah ada dibuka kembali.' : 'Draf koreksi dibuat dari versi terbit. Perubahan baru berlaku setelah diterbitkan.'); window.setTimeout(() => reviewPanelRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0) } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal membuka draf koreksi.') } finally { setBusy(false) } }
  const downloadLayer = async (dataset: GISDataset, format: 'kml' | 'geojson' | 'shp') => { try { await gisApi.downloadDataset(dataset.id, dataset.name, format, dataset.active_version_id ? 'published' : 'draft') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal mengunduh poligon.') } }
  const applyBulkMetadata = async () => { if (!activeImport) return; const defaultAttributes = Object.fromEntries(Object.entries(bulkDraft).filter(([, value]) => String(value).trim() !== '')); if (!Object.keys(defaultAttributes).length) { setMessage('Isi setidaknya satu metadata untuk diterapkan.'); return }; setBusy(true); try { await gisApi.applyMapping(activeImport.id, { default_attributes: defaultAttributes }); await loadDraft(activeImport.id); setBulkDraft({}); setBulkOpen(false); setMessage('Metadata serentak diterapkan. Sistem tetap mempertahankan nilai yang sudah berasal dari KML/KMZ untuk kolom lain.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal menerapkan metadata serentak.') } finally { setBusy(false) } }
  const publish = async () => { if (!activeImport || !selectedDataset || activeImport.state !== 'ready') return; setBusy(true); try { await gisApi.publish(activeImport.id, { expected_active_version_id: selectedDataset.active_version_id, expected_revision: selectedDataset.revision, report_hash: activeImport.report_hash ?? '' }); setMessage('Versi berhasil diterbitkan. Pemeriksaan tumpang tindih tampil sebagai peringatan, bukan blokir.'); setActiveImport(null); setDraftFeatures([]); setPreviewDraftIds(ids => ids.filter(id => id !== selectedDataset.id)); await loadDatasets() } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal menerbitkan versi.') } finally { setBusy(false) } }
  const requiredFields = new Set((missingById.get(selectedFeatureId) ?? '').split(', ').filter(Boolean))

  const renameDataset = async () => { if (!renameTarget || !renameValue.trim()) return; setBusy(true); try { await gisApi.updateDataset(renameTarget.id, { name: renameValue.trim(), expected_revision: renameTarget.revision }); setRenameTarget(null); await Promise.all([loadDatasets(), loadManageDatasets()]); setMessage('Nama layer diperbarui.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal mengubah nama layer.') } finally { setBusy(false) } }
  const toggleArchive = async (dataset: GISDataset) => { setBusy(true); try { if (dataset.archived_at) await gisApi.unarchiveDataset(dataset.id, { expected_revision: dataset.revision }); else await gisApi.archiveDataset(dataset.id, { expected_revision: dataset.revision }); await Promise.all([loadDatasets(), loadManageDatasets()]); setMessage(dataset.archived_at ? 'Layer dipulihkan dari arsip.' : 'Layer diarsipkan dan disembunyikan dari peta. Data tidak hilang.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal mengubah status arsip.') } finally { setBusy(false); setArchiveTarget(null) } }
  const removeDataset = async (dataset: GISDataset) => { setBusy(true); try { await gisApi.deleteDataset(dataset.id, dataset.revision); await Promise.all([loadDatasets(), loadManageDatasets()]); setMessage('Layer draf dihapus.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Gagal menghapus layer.') } finally { setBusy(false); setDeleteTarget(null) } }

  return <div className="space-y-5">
    <div className="flex flex-wrap items-start justify-between gap-3"><div><h1 className="flex items-center gap-2 text-2xl font-bold text-gray-900"><Map className="text-[#1B4F72]" /> Peta GIS Aset</h1><p className="mt-1 text-sm text-gray-500">Konsesi adalah dasar; tanaman, kawasan hutan, OPSET, okupasi, dan batas referensi tampil sebagai layer terpisah.</p></div>{canUpload && <div className="flex flex-wrap gap-2"><input ref={uploadInputRef} className="hidden" type="file" accept=".kml,.kmz,.geojson,.json,.zip,.gpkg" onChange={event => { beginUpload(event.target.files?.[0]); event.currentTarget.value = '' }} /><Button disabled={busy} onClick={() => { setWorkspace('peta'); uploadInputRef.current?.click() }}><FileUp size={16} /> Unggah KML</Button><Button variant="outline" disabled={busy} onClick={() => { setWorkspace('peta'); setCreateOpen(true) }}><Plus size={16} /> Buat layer kosong</Button></div>}</div>
    {message && <div className={`rounded-md border p-3 text-sm ${message.startsWith('Impor gagal:') ? 'border-red-200 bg-red-50 text-red-800' : 'border-slate-200 bg-slate-50 text-slate-700'}`} role="status">{message}</div>}
    <div className="flex w-fit overflow-hidden rounded-md border bg-white text-sm"><button type="button" onClick={() => setWorkspace('peta')} className={`px-4 py-2 ${workspace === 'peta' ? 'bg-[#1B4F72] text-white' : 'hover:bg-slate-50'}`}>GIS</button><button type="button" onClick={() => setWorkspace('aset')} className={`border-l px-4 py-2 ${workspace === 'aset' ? 'bg-[#1B4F72] text-white' : 'hover:bg-slate-50'}`}>Tabel Konsesi</button><button type="button" onClick={() => setWorkspace('kelola')} className={`border-l px-4 py-2 ${workspace === 'kelola' ? 'bg-[#1B4F72] text-white' : 'hover:bg-slate-50'}`}>Kelola Data KML</button></div>
    {workspace === 'aset' && <GISAssetTable onShowMap={asset => { setEnabled(current => Array.from(new Set([...current, ...asset.dataset_ids]))); setZoomTarget(null); setAssetFocusBbox(asset.bbox); setWorkspace('peta') }} />}
    {workspace === 'kelola' && <Card><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle>Kelola data dan informasi GIS</CardTitle><CardDescription>Koreksi atribut poligon, unduh data lengkap, ubah nama, arsipkan, atau hapus layer draf yang gagal.</CardDescription></div><label className="flex items-center gap-2 text-sm text-slate-600"><input type="checkbox" checked={manageShowArchived} onChange={() => setManageShowArchived(value => !value)} /> Tampilkan yang diarsipkan</label></div></CardHeader><CardContent className="space-y-2">{manageDatasets.length === 0 ? <p className="rounded bg-slate-50 p-3 text-sm text-slate-600">Belum ada layer. Unggah KML untuk mulai membentuk data aset.</p> : manageDatasets.map(dataset => <div key={dataset.id} className={`flex flex-wrap items-center justify-between gap-3 rounded-md border p-3 ${dataset.archived_at ? 'bg-slate-50 opacity-75' : ''}`}><div><p className="flex items-center gap-2 font-medium">{dataset.name}{dataset.archived_at && <span className="rounded bg-slate-200 px-1.5 py-0.5 text-xs font-normal text-slate-600">Diarsipkan</span>}</p><p className="text-xs text-slate-500">{KIND_LABEL[dataset.kind]} · {dataset.active_version_id ? `versi ${dataset.active_version_no ?? ''} diterbitkan` : 'draf / belum diterbitkan'}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => manageLayer(dataset)}>Kelola informasi</Button><Button size="sm" variant="outline" disabled={busy || !capabilities?.domains.includes(DOMAIN_BY_KIND[dataset.kind])} onClick={() => void beginEdit(dataset)}><Pencil size={14} /> Edit atribut</Button><Button size="sm" variant="outline" disabled={!dataset.active_version_id && !capabilities?.domains.includes(DOMAIN_BY_KIND[dataset.kind])} onClick={() => void downloadLayer(dataset, "kml")}><Download size={14} /> KML</Button><Button size="sm" variant="outline" disabled={!dataset.active_version_id && !capabilities?.domains.includes(DOMAIN_BY_KIND[dataset.kind])} onClick={() => void downloadLayer(dataset, "geojson")}><Download size={14} /> GeoJSON</Button><Button size="sm" variant="outline" disabled={!dataset.active_version_id && !capabilities?.domains.includes(DOMAIN_BY_KIND[dataset.kind])} onClick={() => void downloadLayer(dataset, "shp")}><Download size={14} /> SHP ZIP</Button><Button size="sm" variant="outline" title="Ubah nama layer" onClick={() => { setRenameTarget(dataset); setRenameValue(dataset.name) }}><Pencil size={14} /></Button><Button size="sm" variant="outline" title={dataset.archived_at ? 'Pulihkan dari arsip' : 'Arsipkan layer'} onClick={() => setArchiveTarget(dataset)}>{dataset.archived_at ? <ArchiveRestore size={14} /> : <Archive size={14} />}</Button><Button size="sm" variant="outline" className="text-red-600 hover:text-red-700" disabled={Boolean(dataset.active_version_id)} title={dataset.active_version_id ? 'Layer sudah punya versi terbitan — arsipkan, bukan hapus' : 'Hapus layer draf ini'} onClick={() => setDeleteTarget(dataset)}><Trash2 size={14} /></Button></div></div>)}</CardContent></Card>}
    <Dialog open={Boolean(renameTarget)} onOpenChange={open => { if (!open) setRenameTarget(null) }}><DialogContent><DialogHeader><DialogTitle>Ubah nama layer</DialogTitle></DialogHeader><div className="space-y-2"><Label>Nama layer</Label><Input value={renameValue} onChange={event => setRenameValue(event.target.value)} /></div><DialogFooter><Button variant="outline" onClick={() => setRenameTarget(null)}>Batal</Button><Button disabled={busy || !renameValue.trim()} onClick={() => void renameDataset()}>Simpan</Button></DialogFooter></DialogContent></Dialog>
    <ConfirmDialog open={Boolean(archiveTarget)} onOpenChange={open => { if (!open) setArchiveTarget(null) }} title={archiveTarget?.archived_at ? 'Pulihkan layer?' : 'Arsipkan layer?'} description={archiveTarget?.archived_at ? `"${archiveTarget?.name}" akan tampil kembali di daftar layer aktif.` : `"${archiveTarget?.name}" akan disembunyikan dari peta dan daftar layer aktif. Data tidak dihapus dan dapat dipulihkan kapan saja.`} confirmLabel={archiveTarget?.archived_at ? 'Pulihkan' : 'Arsipkan'} onConfirm={() => { if (archiveTarget) void toggleArchive(archiveTarget) }} />
    <ConfirmDialog open={Boolean(deleteTarget)} onOpenChange={open => { if (!open) setDeleteTarget(null) }} title="Hapus layer draf?" description={`"${deleteTarget?.name}" akan dihapus permanen beserta riwayat impornya. Tindakan ini hanya tersedia karena layer ini belum pernah punya versi terbitan.`} confirmLabel="Hapus" isDestructive onConfirm={() => { if (deleteTarget) void removeDataset(deleteTarget) }} />
    {workspace === 'peta' && <>
    {capabilities && !canUpload && <div className="rounded-md border border-blue-200 bg-blue-50 p-3 text-sm text-blue-900" role="status">Semua layer GIS, termasuk poligon yang masih draf, dapat dilihat. Pengubahan data membutuhkan izin GIS.</div>}
    <div className="grid gap-5 lg:grid-cols-[2fr_340px]">
      <Card><CardContent className="p-3"><AsetMap data={mapFeatures} onViewportChange={setBbox} focusBbox={assetFocusBbox ?? adminRegions.find(region => region.region_code === adminCode)?.bbox} zoomTarget={zoomTarget} /></CardContent></Card>
      <div className="space-y-4">
        <Card><CardHeader className="pb-3"><CardTitle className="text-base">Filter peta</CardTitle><CardDescription>Batasi layer dan area spesifik.</CardDescription></CardHeader><CardContent className="space-y-3"><div><Label>Jenis layer</Label><Select value={layerKindFilter} onValueChange={value => { setLayerKindFilter(value as GISKind | 'all'); if (value !== 'hutan') setHutanFunction('all') }}><SelectTrigger className="mt-1"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Semua layer</SelectItem>{Object.entries(KIND_LABEL).map(([kind, label]) => <SelectItem key={kind} value={kind}>{label}</SelectItem>)}</SelectContent></Select></div>{layerKindFilter === 'hutan' && <div><Label>Fungsi kawasan hutan</Label><Select value={hutanFunction} onValueChange={setHutanFunction}><SelectTrigger className="mt-1"><SelectValue placeholder="Semua fungsi" /></SelectTrigger><SelectContent><SelectItem value="all">Semua fungsi</SelectItem>{hutanFunctions.map(functionName => <SelectItem key={functionName} value={functionName}>{functionName}</SelectItem>)}</SelectContent></Select></div>}<div className="grid grid-cols-2 gap-2"><div><Label>Tingkat batas</Label><Select value={adminLevel} onValueChange={value => setAdminLevel(value as GISAdministrasiReference['level'] | 'all')}><SelectTrigger className="mt-1"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Tidak dibatasi</SelectItem>{Object.entries(ADMIN_LEVEL_LABEL).map(([level, label]) => <SelectItem key={level} value={level}>{label}</SelectItem>)}</SelectContent></Select></div><div><Label>Wilayah</Label><Select value={adminCode} disabled={adminLevel === 'all'} onValueChange={setAdminCode}><SelectTrigger className="mt-1"><SelectValue placeholder="Pilih wilayah" /></SelectTrigger><SelectContent>{adminRegions.map(region => <SelectItem key={`${region.level}-${region.region_code}`} value={region.region_code}>{region.region_name}</SelectItem>)}</SelectContent></Select></div></div>{adminLevel !== 'all' && adminRegions.length === 0 && <p className="text-xs text-slate-500">Belum ada batas {ADMIN_LEVEL_LABEL[adminLevel].toLowerCase()} yang diterbitkan.</p>}</CardContent></Card>
        <Card><CardHeader className="pb-3"><CardTitle className="flex items-center gap-2 text-base"><Layers3 size={17} /> Layer aktif</CardTitle></CardHeader><CardContent className="space-y-2">{filteredDatasets.length === 0 ? <p className="text-sm text-slate-500">Belum ada layer sesuai filter.</p> : filteredDatasets.map(item => <label key={item.id} className="flex cursor-pointer items-center gap-2 rounded-md border p-2 text-sm"><input type="checkbox" checked={enabled.includes(item.id)} onChange={() => setEnabled(current => current.includes(item.id) ? current.filter(id => id !== item.id) : [...current, item.id])} /><span className={`rounded px-1.5 py-0.5 text-xs font-medium ${KIND_COLOR[item.kind]}`}>{KIND_LABEL[item.kind]}</span><span className="min-w-0 flex-1 truncate">{item.name}</span><button type="button" className="text-xs text-[#1B4F72]" onClick={event => { event.preventDefault(); event.stopPropagation(); manageLayer(item) }}>Kelola</button><button type="button" className="text-[#1B4F72]" title={`Zoom ke ${item.name}`} aria-label={`Zoom ke ${item.name}`} onClick={event => { event.preventDefault(); event.stopPropagation(); void zoomToLayer(item) }}><Crosshair size={16} /></button></label>)}</CardContent></Card>
        <Card ref={managePanelRef}><CardHeader className="pb-3"><CardTitle className="text-base">Tambah atau perbarui layer</CardTitle><CardDescription>{selectedDataset ? `${KIND_LABEL[selectedDataset.kind]} · ${selectedDataset.name}` : 'Pilih layer terlebih dahulu'}</CardDescription></CardHeader><CardContent className="space-y-3">{selectedDataset && <><Label htmlFor="gis-file">Berkas sumber</Label><Input id="gis-file" type="file" accept=".kml,.kmz,.geojson,.json,.zip,.gpkg" disabled={!canWrite || busy} onChange={event => void upload(event.target.files?.[0])} /><p className="text-xs text-slate-500">KML, KMZ, GeoJSON, Shapefile ZIP, atau GeoPackage · maks. 50 MB.</p><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" disabled={!canWrite || busy} onClick={() => void beginEdit(selectedDataset)}><Pencil size={14} /> Edit informasi poligon</Button><Button size="sm" variant="outline" disabled={!canDownloadSelected} onClick={() => void downloadLayer(selectedDataset, "kml")}><Download size={14} /> KML</Button><Button size="sm" variant="outline" disabled={!canDownloadSelected} onClick={() => void downloadLayer(selectedDataset, "geojson")}><Download size={14} /> GeoJSON</Button><Button size="sm" variant="outline" disabled={!canDownloadSelected} onClick={() => void downloadLayer(selectedDataset, "shp")}><Download size={14} /> SHP ZIP</Button></div><p className="rounded bg-blue-50 p-2 text-xs text-blue-900"><FileUp className="mr-1 inline h-3.5 w-3.5" />Atribut yang ada di berkas akan diisi otomatis. Setelah itu, lengkapi hanya kolom yang masih kosong.</p>{selectedDataset.active_version_id && (activeImport || activeDraftLayers.some(layer => layer.dataset.id === selectedDataset.id)) && <label className="flex items-center gap-2 rounded border p-2 text-sm text-slate-700"><input type="checkbox" checked={previewDraftIds.includes(selectedDataset.id)} onChange={() => setPreviewDraftIds(ids => ids.includes(selectedDataset.id) ? ids.filter(id => id !== selectedDataset.id) : [...ids, selectedDataset.id])} />Pratinjau draf koreksi (garis putus-putus)</label>}{!canWrite && <p className="text-sm text-amber-700">Akun ini hanya dapat melihat layer ini.</p>}{overlaps?.state === 'complete' && overlaps.data.length > 0 && <div className="rounded border border-amber-200 bg-amber-50 p-2 text-xs text-amber-950"><p className="font-semibold">Peringatan tumpang tindih ({overlaps.data.length})</p>{overlaps.data.slice(0, 3).map(item => <p key={`${item.target_name}-${item.warning_code}`}>{item.target_name}: {item.intersection_area_m2.toLocaleString('id-ID')} m² dengan {KIND_LABEL[item.relation_kind]}</p>)}</div>}</>}</CardContent></Card>
      </div>
    </div>
    {pendingFile && <Card className="border-2 border-[#1B4F72]"><CardHeader className="border-b"><CardTitle>{uploadDatasetId === 'new' ? 'Tambahkan KML sebagai layer baru' : 'Perbarui layer dengan KML ini'}</CardTitle><CardDescription>{pendingFile.name}. Pilih jenis data dan layer tujuan, lalu unggah. Peta tetap dapat digunakan.</CardDescription></CardHeader><CardContent className="grid gap-4 p-4 md:grid-cols-[1fr_1fr_1fr_auto]"><div><Label>Jenis data</Label><Select value={uploadKind} onValueChange={value => { setUploadKind(value as GISKind); setUploadDatasetId('new') }}><SelectTrigger className="mt-1"><SelectValue /></SelectTrigger><SelectContent>{Object.entries(KIND_LABEL).map(([kind, label]) => <SelectItem key={kind} value={kind}>{label}</SelectItem>)}</SelectContent></Select></div><div><Label>Layer tujuan</Label><Select value={uploadDatasetId} onValueChange={setUploadDatasetId}><SelectTrigger className="mt-1"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="new">Buat layer baru</SelectItem>{datasets.filter(item => item.kind === uploadKind).map(item => <SelectItem key={item.id} value={item.id}>{item.name}</SelectItem>)}</SelectContent></Select></div><div>{uploadDatasetId === 'new' ? <><Label>Nama layer baru</Label><Input className="mt-1" value={uploadLayerName} onChange={event => setUploadLayerName(event.target.value)} /></> : <><Label>Versi baru untuk</Label><p className="mt-3 truncate text-sm font-medium text-slate-700">{datasets.find(item => item.id === uploadDatasetId)?.name}</p></>}</div><div className="flex items-end gap-2"><Button variant="outline" disabled={busy} onClick={() => setPendingFile(null)}>Batal</Button><Button disabled={busy} onClick={() => void confirmUpload()}>{uploadDatasetId === 'new' ? 'Tambah layer baru' : 'Perbarui layer'}</Button></div><p className="md:col-span-4 rounded bg-blue-50 p-2 text-xs text-blue-900">Berkas dibaca terlebih dahulu. Nilai yang ada di KML/KMZ diisi otomatis; setelah itu, hanya informasi yang tidak ada yang diminta pada review metadata.</p></CardContent></Card>}
    {activeImport && selectedDataset && <Card ref={reviewPanelRef}><CardHeader className="border-b"><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle>Review metadata: {selectedDataset.name}</CardTitle><CardDescription>{draftFeatures.length} bidang dibaca dari berkas. {missingSummary.length ? `Data yang belum ada: ${missingSummary.map(([field, count]) => `${FIELD_LABEL[field] ?? field} (${count})`).join(', ')}.` : 'Seluruh metadata minimum sudah tersedia.'} Nilai dari KML/KMZ dipakai otomatis.</CardDescription></div><Button type="button" variant="outline" disabled={busy} onClick={() => setBulkOpen(open => !open)}>Isi metadata seragam</Button></div></CardHeader><CardContent className="space-y-4 p-4">{bulkOpen && <div className="rounded-md border border-blue-200 bg-blue-50 p-3"><p className="mb-3 text-sm font-medium text-blue-950">Gunakan hanya jika nilainya sama untuk bidang yang masih kurang. Kolom kosong tidak akan mengubah data yang sudah dibaca dari KML/KMZ.</p><div className="grid gap-3 md:grid-cols-3">{FIELDS[selectedDataset.kind].map(field => <div key={field.key}><Label>{field.label}</Label>{field.type === 'select' ? <Select value={String(bulkDraft[field.key] ?? '')} onValueChange={value => setBulkDraft(current => ({ ...current, [field.key]: value }))}><SelectTrigger className="mt-1"><SelectValue placeholder="Jangan diubah" /></SelectTrigger><SelectContent>{field.options?.map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select> : <Input className="mt-1" type={field.type ?? 'text'} value={String(bulkDraft[field.key] ?? '')} onChange={event => setBulkDraft(current => ({ ...current, [field.key]: event.target.value }))} />}</div>)}</div><Button className="mt-3" disabled={busy} onClick={() => void applyBulkMetadata()}>Terapkan ke bidang yang diimpor</Button></div>}<div className="grid gap-5 lg:grid-cols-[300px_minmax(0,1fr)]"><div className="space-y-3"><div className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" /><Input className="pl-9" value={featureSearch} onChange={event => setFeatureSearch(event.target.value)} placeholder="Cari nama atau data kurang" /></div><div className="max-h-80 space-y-1 overflow-y-auto pr-1">{reviewFeatures.map(item => <button type="button" key={item.id} className={`block w-full rounded-md border p-2 text-left text-sm ${selectedFeatureId === item.id ? 'border-[#1B4F72] bg-blue-50' : 'hover:bg-slate-50'}`} onClick={() => setSelectedFeatureId(item.id)}><span className="block truncate font-medium">{item.name}</span><span className={`block text-xs ${missingById.has(item.id) ? 'text-amber-700' : 'text-emerald-700'}`}>{missingById.get(item.id) ? `Perlu: ${missingById.get(item.id)}` : 'Lengkap'} · {item.computed_area_m2.toLocaleString('id-ID')} m²</span></button>)}</div></div>{selectedFeature && <div className="space-y-4"><div><Label htmlFor="feature-name">Nama poligon</Label><Input id="feature-name" className="mt-1" value={featureName} onChange={event => setFeatureName(event.target.value)} /><p className="mt-1 text-xs text-slate-500">Koreksi nama dan atribut sumber di bawah, lalu simpan bidang.</p></div><div className="grid gap-3 md:grid-cols-2">{FIELDS[selectedDataset.kind].filter(field => !field.advanced).map(field => <FeatureField key={field.key} field={field} value={draft[field.key] ?? ''} required={requiredFields.has(field.key)} kerjaSama={kerjaSama} onChange={value => setDraft(current => field.key === 'kerja_sama_id' ? { ...current, kerja_sama_id: value, ...(kerjaSama.find(item => item.id === value) ? { nama_mitra: kerjaSama.find(item => item.id === value)!.nama_mitra, no_perjanjian: kerjaSama.find(item => item.id === value)!.no_perjanjian ?? '', skema_kerja_sama: kerjaSama.find(item => item.id === value)!.skema_kerja_sama ?? '', tanggal_mulai: kerjaSama.find(item => item.id === value)!.tgl_mulai ?? '', tanggal_berakhir: kerjaSama.find(item => item.id === value)!.tgl_selesai ?? '' } : {}) } : { ...current, [field.key]: value })} />)}</div><details className="rounded-md border p-3"><summary className="cursor-pointer text-sm font-medium text-[#1B4F72]">Detail lanjutan: alas hak, masa berlaku, dokumen, dan lokasi</summary><div className="mt-3 grid gap-3 md:grid-cols-2">{FIELDS[selectedDataset.kind].filter(field => field.advanced).map(field => <FeatureField key={field.key} field={field} value={draft[field.key] ?? ''} required={requiredFields.has(field.key)} kerjaSama={kerjaSama} onChange={value => setDraft(current => ({ ...current, [field.key]: value }))} />)}</div></details><div className="space-y-2 rounded-md border p-3"><p className="text-sm font-medium">Atribut dari KML/SHP/GeoJSON</p><p className="text-xs text-slate-500">Perbaiki nilai yang salah pada berkas sumber. Berkas asli tetap tersimpan sebagai arsip.</p><div className="grid gap-2 md:grid-cols-2">{Object.entries(sourceDraft).map(([key, value]) => <div key={key}><Label>{key}</Label><Input className="mt-1" value={String(value ?? '')} onChange={event => setSourceDraft(current => ({ ...current, [key]: event.target.value }))} /></div>)}</div><div className="flex gap-2"><Input value={newSourceKey} onChange={event => setNewSourceKey(event.target.value)} placeholder="Nama kolom baru" /><Button type="button" variant="outline" disabled={!newSourceKey.trim() || newSourceKey in sourceDraft} onClick={() => { setSourceDraft(current => ({ ...current, [newSourceKey.trim()]: '' })); setNewSourceKey('') }}>Tambah kolom</Button></div></div>{selectedDataset.kind === 'konsesi' && <div><Label>Link aset</Label><div className="mt-1 max-h-28 space-y-1 overflow-y-auto rounded border p-2 text-sm">{asetReferences.map(aset => <label key={aset.id} className="flex items-center gap-2"><input type="checkbox" checked={linkedAssetIds.includes(aset.id)} onChange={() => setLinkedAssetIds(ids => ids.includes(aset.id) ? ids.filter(id => id !== aset.id) : [...ids, aset.id])} />{aset.kode_aset} · {aset.nama_aset}</label>)}</div></div>}<div className="flex flex-wrap gap-2"><Button disabled={busy} onClick={() => void saveFeature()}>Simpan bidang</Button>{activeImport.state === 'ready' && <Button disabled={busy} className="bg-[#1B4F72]" onClick={() => void publish()}><Upload size={15} /> Terbitkan versi</Button>}</div></div>}</div></CardContent></Card>}
    <Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent><DialogHeader><DialogTitle>Buat layer GIS</DialogTitle></DialogHeader><div className="space-y-4"><div><Label>Jenis layer</Label><Select value={newKind} onValueChange={value => setNewKind(value as GISKind)}><SelectTrigger className="mt-1"><SelectValue /></SelectTrigger><SelectContent>{Object.entries(KIND_LABEL).map(([kind, label]) => <SelectItem key={kind} value={kind}>{label}</SelectItem>)}</SelectContent></Select></div><div><Label>Nama layer</Label><Input className="mt-1" value={newName} onChange={event => setNewName(event.target.value)} placeholder="Contoh: HGU Kebun A" /></div><div><Label>Cakupan (opsional)</Label><Input className="mt-1" value={newScope} onChange={event => setNewScope(event.target.value)} placeholder="Contoh: KEBUN-A atau KABUPATEN-XX" /></div></div><DialogFooter><Button variant="outline" onClick={() => setCreateOpen(false)}>Batal</Button><Button disabled={busy} onClick={() => void createDataset()}>Buat layer</Button></DialogFooter></DialogContent></Dialog>
    </>}
  </div>
}
